import html
P=[]
def mk(lang):
    H={'it':('Link','A cosa serve'),'tr':('Bağlantı','Ne için')}[lang]
    def lr(rows): return table([(f'<strong>{html.escape(t)}</strong><br>{ext(u)}',html.escape(w)) for t,u,w in rows],heads=H)
    return lr
